#include <stdio.h>

int main(void) {
    long long n;
    scanf("%lld", &n);
    if (n == 0) {
        printf("0\n");
        return 0;
    }
    long long p = 1;
    while (p * 2 <= n) {
        p *= 2;
    }
    while (p > 0) {
        if (n >= p) {
            printf("1");
            n -= p;
        } else {
            printf("0");
        }
        p /= 2;
    }
    printf("\n");
    return 0;
}

