int main(void) {
    int n;
    scanf("%d", &n);
    int a, b;
    scanf("%d %d", &a, &b);
    int first = a > b ? a : b;
    int second = a > b ? b : a;
    for (int i = 2; i < n; i++) {
        int x;
        scanf("%d", &x);
        if (x > first) {
            second = first;
            first = x;
        } else if (x > second) {
            second = x;
        }
    }
    printf("%d\n", second);
    return 0;
}

