int main(void) {
    int n;
    scanf("%d", &n);
    int prev;
    scanf("%d", &prev);
    int current = 1, best = 1;
    for (int i = 1; i < n; i++) {
        int x;
        scanf("%d", &x);
        if (x == prev) {
            current++;
        } else {
            current = 1;
        }
        if (current > best) {
            best = current;
        }
        prev = x;
    }
    printf("%d\n", best);
    return 0;
}

