#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int found = 0;
    for (int k = 2; k <= n; k++) {
        int sum = 1;
        for (int d = 2; d * d <= k; d++) {
            if (k % d == 0) {
                sum += d;
                if (d != k / d) {
                    sum += k / d;
                }
            }
        }
        if (sum == k) {
            if (found > 0) {
                printf(" ");
            }
            printf("%d", k);
            found++;
        }
    }
    if (found == 0) {
        printf("нет");
    }
    printf("\n");
    return 0;
}

